#!/usr/bin/env node
/**
 * Turns src/db/schema.ts into idempotent SQL that the app runs on start-up
 * (src/db/schema-sql.ts), so a brand-new database — e.g. a fresh Vercel / Neon
 * Postgres — gets its tables automatically without running drizzle-kit.
 *
 *   npm run db:schema          regenerate after editing src/db/schema.ts
 *   npm run db:schema -- --check   fail if the generated file is stale (CI)
 *
 * Works offline: drizzle-kit `generate` only reads the TypeScript schema.
 */
import { execFileSync } from "node:child_process";
import { mkdtempSync, readdirSync, readFileSync, rmSync, writeFileSync } from "node:fs";
import { tmpdir } from "node:os";
import { join, dirname } from "node:path";
import { fileURLToPath } from "node:url";

const root = join(dirname(fileURLToPath(import.meta.url)), "..");
const outFile = join(root, "src/db/schema-sql.ts");
const check = process.argv.includes("--check");

const tmp = mkdtempSync(join(tmpdir(), "gowayy-schema-"));
try {
  execFileSync(
    process.execPath,
    [join(root, "node_modules/drizzle-kit/bin.cjs"), "generate", "--dialect", "postgresql", "--schema", "./src/db/schema.ts", "--out", tmp],
    { cwd: root, stdio: ["ignore", "ignore", "inherit"] },
  );
  const sqlFile = readdirSync(tmp).find((f) => f.endsWith(".sql"));
  const snapFile = readdirSync(join(tmp, "meta")).find((f) => f.endsWith("_snapshot.json"));
  if (!sqlFile || !snapFile) throw new Error("drizzle-kit produced no migration");

  // 1) CREATE statements, made safe to re-run against an existing database.
  const create = readFileSync(join(tmp, sqlFile), "utf8")
    .split("--> statement-breakpoint")
    .map((s) => s.trim())
    .filter(Boolean)
    .map((s) => {
      if (/^CREATE TABLE "/.test(s)) return s.replace(/^CREATE TABLE /, "CREATE TABLE IF NOT EXISTS ");
      if (/^CREATE (UNIQUE )?INDEX "/.test(s)) return s.replace(/^CREATE (UNIQUE )?INDEX /, (m) => `${m}IF NOT EXISTS `);
      if (/^ALTER TABLE .* ADD CONSTRAINT /s.test(s) || /^CREATE TYPE /.test(s))
        return `DO $$ BEGIN ${s.replace(/;\s*$/, "")}; EXCEPTION WHEN duplicate_object THEN NULL; END $$;`;
      throw new Error(`Unhandled statement in generated schema:\n${s}`);
    });

  // 2) Column upgrades for databases created by an older schema. Only columns
  //    that can be added to a table that already has rows (nullable or with a
  //    default) are included; primary keys are always part of CREATE TABLE.
  const snap = JSON.parse(readFileSync(join(tmp, "meta", snapFile), "utf8"));
  const upgrade = [];
  for (const t of Object.values(snap.tables)) {
    for (const c of Object.values(t.columns)) {
      if (c.primaryKey || c.type === "serial") continue;
      if (c.notNull && c.default === undefined) continue;
      const def = c.default !== undefined ? ` DEFAULT ${c.default}` : "";
      upgrade.push(`ALTER TABLE "${t.name}" ADD COLUMN IF NOT EXISTS "${c.name}" ${c.type}${def}${c.notNull ? " NOT NULL" : ""};`);
    }
  }

  const body = `// AUTO-GENERATED by scripts/generate-schema-sql.mjs from src/db/schema.ts.
// Do not edit by hand — run \`npm run db:schema\` after changing the schema.

/** Idempotent statements that create every table and index. */
export const CREATE_SCHEMA: string[] = ${JSON.stringify(create, null, 2)};

/** Adds columns introduced after a database was first created (safe to re-run). */
export const UPGRADE_COLUMNS: string[] = ${JSON.stringify(upgrade, null, 2)};

/** Changes whenever the schema changes; stored so start-up can skip work that is already done. */
export const SCHEMA_VERSION = ${JSON.stringify(hash(JSON.stringify([create, upgrade])))};
`;

  const current = (() => {
    try {
      return readFileSync(outFile, "utf8");
    } catch {
      return "";
    }
  })();
  if (check) {
    if (current !== body) {
      console.error("src/db/schema-sql.ts is out of date — run `npm run db:schema`.");
      process.exit(1);
    }
    console.log("src/db/schema-sql.ts is up to date.");
  } else {
    writeFileSync(outFile, body);
    console.log(`Wrote src/db/schema-sql.ts (${create.length} create, ${upgrade.length} upgrade statements).`);
  }
} finally {
  rmSync(tmp, { recursive: true, force: true });
}

function hash(s) {
  let h = 0x811c9dc5;
  for (let i = 0; i < s.length; i++) h = Math.imul(h ^ s.charCodeAt(i), 0x01000193) >>> 0;
  return h.toString(16).padStart(8, "0");
}
